// === Tab: Body ===
abstract class Body
{
  xPosition, yPosition;
  xVelocity, yVelocity;
  directionAngle;
  speed;

  function update() {
    xPosition += xVelocity;
    yPosition += yVelocity;
  }
  abstract function display();

  function setVelocity(dir, spd) {
    directionAngle = dir;
    speed = spd;
    xVelocity = speed * cos(dir);
    yVelocity = speed * sin(dir);
  }

  getDistance(other) {
    return dist(this.xPosition, this.yPosition, other.xPosition, other.yPosition);
  }
  getDistancePow2(other) {
    return sq(other.xPosition - this.xPosition) + sq(other.yPosition - this.yPosition);
  }
  getAngle(other) {
    return atan2(other.yPosition - this.yPosition, other.xPosition - this.xPosition);
  }
}

abstract class Actor
  extends Body
{
  let group;
  let rotationAngle;
  let collisionRadius;

  Actor(_collisionRadius) {
    collisionRadius = _collisionRadius;
  }

  abstract function act();

  function isCollided(other) {
    return getDistance(other) < this.collisionRadius + other.collisionRadius;
  }
}


