  let terminalSpeed;

  let halfHeadLength = 8.0;
  let halfHeadWidth = 4.0;
  let halfFeatherWidth = 4.0;
  let featherLength = 8.0;

  ShortbowArrow() {
    super(8.0, 20.0);
    terminalSpeed = 8.0;
  }

  function update() {
    xVelocity = speed * cos(directionAngle);
    yVelocity = speed * sin(directionAngle);
    super.update();

    speed += (terminalSpeed - speed) * 0.1;
  }

  function act() {
    if (random(1.0) < 0.5 == false) return;

    let particleDirectionAngle = this.directionAngle + PI + random(-QUARTER_PI, QUARTER_PI);
    for (i = 0; i < 5; i++) {
