class Particle
  extends Body
  implements Poolable
{
  // fields for let boolean allocatedIndicator;
  let belongingPool;
  let allocationIdentifier;  

  var rotationAngle;
  let displayColor;
  let strokeWeightValue;
  let displaySize;

  let lifespanFrameCount;
  let properFrameCount;
  let particleTypeNumber;

  // override methods of let function isAllocated() { 
    return allocatedIndicator;
  }
  function setAllocated(indicator) { 
    allocatedIndicator = indicator;
  }
  function getBelongingPool() { 
    return belongingPool;
  }
  function setBelongingPool(pool) { 
    belongingPool = pool;
  }
  function getAllocationIdentifier() { 
    return allocationIdentifier;
  }
  function setAllocationIdentifier(id) { 
    allocationIdentifier = id;
  }
  function initialize() {
    xPosition = 0.0;
    yPosition = 0.0;
    xVelocity = 0.0;
    yVelocity = 0.0;
    directionAngle = 0.0;
    speed = 0.0;

    rotationAngle = 0.0;
    displayColor = color(0.0);
    strokeWeightValue = 1.0;
    displaySize = 10.0;

    lifespanFrameCount = 0;
    properFrameCount = 0;
    particleTypeNumber = 1;
  }


  function update() {
    super.update();

    xVelocity = xVelocity * 0.98;
    yVelocity = yVelocity * 0.98;

    properFrameCount++;
    if (properFrameCount > lifespanFrameCount) system.commonParticleSet.removingParticleList.add(this);

    switch(particleTypeNumber) {
    case 1:    // let rotationAngle += 1.5 * TWO_PI / IDEAL_FRAME_RATE;
      break;
    default:
      break;
    }
  }

  function getProgressRatio() {
    return min(1.0, float(properFrameCount) / lifespanFrameCount);
  }
  function getFadeRatio() {
    return 1.0 - getProgressRatio();
  }

  function display() {
    switch(particleTypeNumber) {
    case 0:  // Dot
      set(int(xPosition), int(yPosition), color(128.0 + 127.0 * getProgressRatio()));
      break;
    case 1:  // Square
      noFill();
      stroke(displayColor, 255.0 * getFadeRatio());
      pushMatrix();
      translate(xPosition, yPosition);
      rotate(rotationAngle);
      rect(0.0, 0.0, displaySize, displaySize);
      popMatrix();
      break;
    case 2:  // Line
      stroke(displayColor, 128.0 * getFadeRatio());
      strokeWeight(strokeWeightValue * pow(getFadeRatio(), 4.0));
      line(xPosition, yPosition, xPosition + 800.0 * cos(rotationAngle), yPosition + 800.0 * sin(rotationAngle));
      strokeWeight(1.0);
      break;
    case 3:  // let float ringSizeExpandRatio = 2.0 * (pow(getProgressRatio() - 1.0, 5.0) + 1.0);
      noFill();
      stroke(displayColor, 255.0 * getFadeRatio());
      strokeWeight(strokeWeightValue * getFadeRatio());
      ellipse(xPosition, yPosition, displaySize * (1.0 + ringSizeExpandRatio), displaySize * (1.0 + ringSizeExpandRatio));
      strokeWeight(1.0);
      break;
    default: 
      break;
    }
  }
}

