class HumanPlayerEngine
  extends PlayerEngine
{
  var currentKeyInput;

  HumanPlayerEngine(_keyInput) {
    currentKeyInput = _keyInput;
  }

  function run(player) {
    let intUp = currentKeyInput.isUpPressed ? -10 : 0;
    let intDown = currentKeyInput.isDownPressed ? 10 : 0;
    let intLeft = currentKeyInput.isLeftPressed ? -10 : 0;
    let intRight = currentKeyInput.isRightPressed ? 10 : 0;  

    controllingInputDevice.operateMoveButton(intLeft + intRight, intUp + intDown);
